//! Replays Node StringDecoder('utf8') vectors (tests/data/string_decoder_utf8.json, regenerated by
//! tests/data/gen_string_decoder.mjs) through deckhand_term::utf8::Utf8Decoder.

use deckhand_term::utf8::Utf8Decoder;
use serde_json::Value;

fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd hex length: {text}");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex byte"))
        .collect()
}

#[test]
fn matches_node_string_decoder_vectors() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/string_decoder_utf8.json");
    let data: Value = serde_json::from_str(&std::fs::read_to_string(path).expect("read vectors")).expect("parse");
    let cases = data["cases"].as_array().expect("cases");
    assert!(cases.len() > 600, "expected the recorded corpus");
    let mut failures = Vec::new();
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let chunks: Vec<Vec<u8>> = case["chunks"]
            .as_array()
            .expect("chunks")
            .iter()
            .map(|chunk| unhex(chunk.as_str().expect("hex")))
            .collect();
        let expected: Vec<&str> = case["writes"]
            .as_array()
            .expect("writes")
            .iter()
            .map(|w| w.as_str().expect("str"))
            .collect();
        let expected_end = case["end"].as_str().expect("end");
        let mut decoder = Utf8Decoder::new();
        let writes: Vec<String> = chunks.iter().map(|chunk| decoder.write(chunk)).collect();
        let end = decoder.end();
        if writes != expected || end != expected_end {
            failures.push(format!(
                "{name}: got {writes:?} end {end:?}, want {expected:?} end {expected_end:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn decoder_is_reusable_after_end() {
    let mut decoder = Utf8Decoder::new();
    assert_eq!(decoder.write(&[0xE2]), "");
    assert_eq!(decoder.end(), "\u{FFFD}");
    assert_eq!(decoder.write("é".as_bytes()), "é");
}
